"""Demo: minimal Chebyshev covering radius as a step function of the sample budget.

Computes minRad(m, n), the least l-infinity radius at which the 1-D grid {0,...,m-1}
can be covered using at most n landmarks, and displays the staircase that disproves
the exact power law epsilon = C/n.
"""
from __future__ import annotations
import math
from typing import Dict

def coverable_1d(m: int, n: int, r: int) -> bool:
    return math.ceil(m / (2 * r + 1)) <= n

def min_radius_1d(m: int, n: int) -> int:
    r = 0
    while not coverable_1d(m, n, r):
        r += 1
    return r

def radius_table(m: int) -> Dict[int, int]:
    return {n: min_radius_1d(m, n) for n in range(1, m + 1)}

if __name__ == "__main__":
    m = 7
    table = radius_table(m)
    for n, r in table.items():
        print(f"minRad({m},{n}) = {r}")
    assert table[3] == table[4] == 1, "step-function witness failed"
    print("minRad(7,3) == minRad(7,4) == 1  ->  no exact C/n law exists.")

"""Demo: the provably optimal grid r-cover attains the packing lower bound.

For a cube of side m = (2r+1)*t in dimension d, builds the t^d block-center product
cover and verifies (a) it is a genuine r-cover and (b) its size equals the packing
lower bound ceil(m^d / (2r+1)^d), i.e. the exponent -1/d is sharp.
"""
from __future__ import annotations
import itertools, math
from typing import List, Sequence, Tuple

def cheb_distance(x: Sequence[int], s: Sequence[int]) -> int:
    return max(abs(int(a) - int(b)) for a, b in zip(x, s))

def grid_cube(m: int, d: int) -> List[Tuple[int, ...]]:
    return list(itertools.product(range(m), repeat=d))

def grid_cover(r: int, t: int, d: int) -> List[Tuple[int, ...]]:
    centers = [k * (2 * r + 1) + r for k in range(t)]
    return list(itertools.product(centers, repeat=d))

def verify(r: int, t: int, d: int) -> Tuple[bool, int, int]:
    m = (2 * r + 1) * t
    cover = grid_cover(r, t, d)
    pts = grid_cube(m, d)
    is_cover = all(any(cheb_distance(x, s) <= r for s in cover) for x in pts)
    lower = math.ceil(m ** d / (2 * r + 1) ** d)
    return is_cover, len(cover), lower

if __name__ == "__main__":
    for (r, t, d) in [(1, 3, 2), (1, 2, 3), (2, 2, 2)]:
        ok, size, lower = verify(r, t, d)
        print(f"r={r}, t={t}, d={d}: is_cover={ok}, |S|={size}, "
              f"packing_bound={lower}, sharp={size == lower}")

"""Demo: the sharp l-infinity to l2 comparison and the sqrt(d) worst case.

Verifies ||x||_inf <= ||x||_2 <= sqrt(d) ||x||_inf for random-ish vectors and shows
that the upper constant sqrt(d) is attained exactly by the all-ones vector -- the
origin of the d^{1/2} prefactor in the detection threshold.
"""
from __future__ import annotations
import math
from typing import List, Sequence

def linf(x: Sequence[float]) -> float:
    return max(abs(v) for v in x)

def l2(x: Sequence[float]) -> float:
    return math.sqrt(sum(v * v for v in x))

def two_sided_holds(x: Sequence[float]) -> bool:
    d = len(x)
    return linf(x) <= l2(x) + 1e-12 and l2(x) <= math.sqrt(d) * linf(x) + 1e-9

if __name__ == "__main__":
    for d in [1, 2, 3, 5, 10]:
        ones: List[float] = [1.0] * d
        print(f"d={d:2d}: ||1||_2/||1||_inf = {l2(ones)/linf(ones):.6f}  "
              f"(sqrt(d) = {math.sqrt(d):.6f})")
    samples = [[3.0, -1.0], [2.0, 2.0, 1.0], [0.0, 5.0, -5.0, 1.0]]
    print("two-sided inequality holds on all samples:",
          all(two_sided_holds(x) for x in samples))

